"""Families of theorems generated by Python, all checked by Lean in one run.

1. A loop builds, for n = 2..6, the statement
       (x₁ + … + xₙ)² ≤ n · (x₁² + … + xₙ²)
   *and* its proof: one hint sq_nonneg(xᵢ - xⱼ) per pair i < j, because
       n·Σxᵢ² - (Σxᵢ)² = Σ_{i<j} (xᵢ - xⱼ)².
2. A dataset of claimed Pythagorean triples (from Euclid's formula, plus one bad row)
   becomes one theorem per row; Lean must accept the good rows and reject the bad one.

Run:  python examples/theorem_families.py
"""

from __future__ import annotations

from itertools import combinations

import pyleanx as pl
from pyleanx import algebra as alg

# ---------------------------------------------------------------- family 1: a loop
family = []
for n in range(2, 7):
    xs = pl.symbols(" ".join(f"x{i}" for i in range(1, n + 1)), pl.Real)
    total = sum(xs[1:], xs[0])
    squares = sum((x**2 for x in xs[1:]), xs[0] ** 2)
    hints = [alg.sq_nonneg(a - b) for a, b in combinations(xs, 2)]
    family.append(pl.Theorem(f"sum_sq_le_{n}", list(xs),
                             conclusion=total**2 <= n * squares,
                             proof=pl.linarith(*hints)))

# ---------------------------------------------------------------- family 2: a dataset
rows = [(m * m - k * k, 2 * m * k, m * m + k * k)            # Euclid: m > k > 0
        for m in range(2, 6) for k in range(1, m)]
rows.append((6, 8, 11))                                      # a bad row: 36 + 64 ≠ 121
triples = [pl.Theorem(f"triple_{a}_{b}_{c}",
                      conclusion=pl.nat(a)**2 + pl.nat(b)**2 == pl.nat(c)**2,
                      proof=pl.norm_num())
           for a, b, c in rows]

# ---------------------------------------------------------------- one Lean run
theorems = family + triples
results = pl.verify_all(theorems, timeout=1800)
for t, r in zip(theorems, results, strict=True):
    print(f"{r.status.value:9s} {t.name:24s} {t.to_latex()}")

expected_bad = {"triple_6_8_11"}
ok = all(r.verified != (t.name in expected_bad) for t, r in zip(theorems, results, strict=True))
print(f"\n{sum(r.verified for r in results)}/{len(results)} verified; "
      f"{'as expected' if ok else 'UNEXPECTED'}: the bad row was "
      f"{'rejected' if not results[-1].verified else 'accepted'}")
raise SystemExit(0 if ok else 1)
